// Calculate engagement velocity, momentum score, and activity patterns
const deal = $input.item.json;

// Extract deal basic info
const dealId = deal.id || deal.Deal_ID || 'unknown';
const dealName = deal.Deal_Name || deal.name || 'Unnamed Deal';
const dealValue = deal.Amount || deal.value || 0;

// Get activities (assuming they're in the deal data)
const activities = deal.Activities || deal.activities || [];

// Calculate date ranges
const now = new Date();
const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
const fifteenDaysAgo = new Date(now.getTime() - 15 * 24 * 60 * 60 * 1000);

// Filter activities by time period
const last30DaysActivities = activities.filter(activity => {
  const activityDate = new Date(activity.date || activity.Created_Time);
  return activityDate >= thirtyDaysAgo && activityDate <= now;
});

const last15DaysActivities = activities.filter(activity => {
  const activityDate = new Date(activity.date || activity.Created_Time);
  return activityDate >= fifteenDaysAgo && activityDate <= now;
});

const first15DaysActivities = activities.filter(activity => {
  const activityDate = new Date(activity.date || activity.Created_Time);
  return activityDate >= thirtyDaysAgo && activityDate < fifteenDaysAgo;
});

// Calculate velocity (activities per week)
const currentVelocity = (last15DaysActivities.length / 15) * 7; // Convert to per week
const previousVelocity = (first15DaysActivities.length / 15) * 7; // Convert to per week
const averageVelocity = (last30DaysActivities.length / 30) * 7;

// Calculate activity frequency (activities per day over 30 days)
const activityFrequency = last30DaysActivities.length / 30;

// Calculate days since last activity
let daysSinceLastActivity = null;
if (activities.length > 0) {
  const sortedActivities = activities.sort((a, b) => {
    const dateA = new Date(a.date || a.Created_Time);
    const dateB = new Date(b.date || b.Created_Time);
    return dateB - dateA;
  });
  const lastActivityDate = new Date(sortedActivities[0].date || sortedActivities[0].Created_Time);
  daysSinceLastActivity = Math.floor((now - lastActivityDate) / (24 * 60 * 60 * 1000));
} else {
  daysSinceLastActivity = 999; // No activities found
}

// Calculate momentum score (0-100)
let momentumScore = 0;

// Factor 1: Current velocity (40 points max)
const velocityScore = Math.min((currentVelocity / 5) * 40, 40); // 5 activities/week = max

// Factor 2: Velocity trend (30 points max)
const velocityChange = currentVelocity - previousVelocity;
const trendScore = velocityChange > 0 ? Math.min((velocityChange / 2) * 30, 30) : 0;

// Factor 3: Recency (30 points max)
const recencyScore = daysSinceLastActivity <= 3 ? 30 : 
                     daysSinceLastActivity <= 7 ? 20 : 
                     daysSinceLastActivity <= 14 ? 10 : 0;

momentumScore = Math.round(velocityScore + trendScore + recencyScore);

// Determine momentum trend
let momentumTrend = 'stable';
const velocityChangePercent = previousVelocity > 0 ? 
  ((currentVelocity - previousVelocity) / previousVelocity) * 100 : 0;

if (velocityChangePercent > 20) {
  momentumTrend = 'increasing';
} else if (velocityChangePercent < -20) {
  momentumTrend = 'decreasing';
}

// Determine if deal is slowing
const isSlowing = currentVelocity < previousVelocity && 
                  currentVelocity < averageVelocity * 0.7;

// Return the calculated metrics
return {
  dealId: dealId,
  dealName: dealName,
  dealValue: dealValue,
  currentVelocity: Math.round(currentVelocity * 100) / 100,
  previousVelocity: Math.round(previousVelocity * 100) / 100,
  momentumScore: momentumScore,
  daysSinceLastActivity: daysSinceLastActivity,
  activityFrequency: Math.round(activityFrequency * 100) / 100,
  momentumTrend: momentumTrend,
  isSlowing: isSlowing,
  totalActivitiesLast30Days: last30DaysActivities.length,
  velocityChangePercent: Math.round(velocityChangePercent * 100) / 100
};

