return items.map(item => {

  // Step 1: Parse AI output
  let parsed;

  if (typeof item.json.output === "string") {
    try {
      parsed = JSON.parse(item.json.output);
    } catch (e) {
      throw new Error("Invalid JSON from AI: " + item.json.output);
    }
  } else {
    parsed = item.json.output;
  }

  // Step 2: Build tactics text
  let tacticsText = "";

  parsed.tactics.forEach((t, index) => {
    tacticsText += `\n${index + 1}. ${t.title}\n- ${t.action}\n- Next: ${t.next_step}\n`;
  });

  // Step 3: Return one item per input
  return {
    json: {
      dealId: item.json.dealId,
      dealName: item.json.dealName,
      priority: parsed.priority,
      reason: parsed.reason,
      alertMessage: `Deal Momentum Alert: ${item.json.dealName}

Deal Value: $${item.json.dealValue}
Momentum Score: ${item.json.momentumScore}/100
Days Since Last Activity: ${item.json.daysSinceLastActivity}
Trend: ${item.json.momentumTrend}
Priority: ${parsed.priority.toUpperCase()}

Recommended Tactics:
${tacticsText}

Reason: ${parsed.reason}`
    }
  };
});
